create or replace function public.check_and_increment_usage_v2(p_user_id uuid,p_tool_id text,p_required_plan text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_profile public.profiles%ROWTYPE;v_today date:=current_date;v_month text:=to_char(current_date,'YYYY-MM');v_is_admin boolean:=false;v_tier text;v_tier_rank integer;v_required_rank integer;v_daily_limit integer;v_monthly_limit integer;v_used_today integer;v_used_month integer;v_trial_remaining integer;v_trial_expired boolean;v_bonus integer;begin if auth.uid() is null or(auth.uid()<>p_user_id and not public.has_role(auth.uid(),'admin'::public.app_role))then raise exception 'Not authorized to check usage for this user';end if;select * into v_profile from public.profiles where id=p_user_id for update;if not found then return jsonb_build_object('allowed',false,'error','Profile not found');end if;v_is_admin:=public.has_role(p_user_id,'admin'::public.app_role);v_tier:=coalesce(v_profile.subscription_tier,'free');if v_is_admin then v_tier:='pro';end if;v_tier_rank:=case v_tier when 'pro' then 2 when 'creator' then 1 else 0 end;v_required_rank:=case p_required_plan when 'pro' then 2 when 'creator' then 1 else 0 end;if v_tier_rank<v_required_rank then v_trial_expired:=v_profile.trial_ends_at is not null and v_profile.trial_ends_at<now();v_trial_remaining:=greatest(0,coalesce(v_profile.premium_trial_limit,3)-coalesce(v_profile.premium_trial_used,0));if v_profile.trial_active and not v_trial_expired and v_trial_remaining>0 then update public.profiles set premium_trial_used=coalesce(premium_trial_used,0)+1,updated_at=now() where id=p_user_id;return jsonb_build_object('allowed',true,'tier',v_tier,'trial',true,'trial_remaining',v_trial_remaining-1);end if;return jsonb_build_object('allowed',false,'code',case when v_profile.trial_active then 'TRIAL_EXHAUSTED' else 'UPGRADE_REQUIRED' end,'tier',v_tier,'required',p_required_plan,'trial_available',not v_profile.trial_active and coalesce(v_profile.premium_trial_used,0)=0,'error',case when v_profile.trial_active then 'Free trial exhausted' else 'Start free trial or upgrade' end);end if;if v_tier='pro' then v_daily_limit:=-1;v_monthly_limit:=-1;elsif v_tier='creator' then v_daily_limit:=-1;v_monthly_limit:=50;else v_daily_limit:=5;v_monthly_limit:=-1;end if;v_used_today:=case when v_profile.last_generation_date is null or v_profile.last_generation_date<v_today then 0 else coalesce(v_profile.generations_today,0) end;v_used_month:=case when v_profile.last_generation_month is null or v_profile.last_generation_month<>v_month then 0 else coalesce(v_profile.generations_this_month,0) end;v_bonus:=coalesce(v_profile.referral_bonus_credits,0);if v_daily_limit>0 and v_used_today>=v_daily_limit then if v_bonus>0 then update public.profiles set referral_bonus_credits=v_bonus-1,updated_at=now() where id=p_user_id;return jsonb_build_object('allowed',true,'tier',v_tier,'bonus',true,'bonus_remaining',v_bonus-1,'remaining_today',0);end if;return jsonb_build_object('allowed',false,'code','DAILY_LIMIT','tier',v_tier,'error','Daily limit reached');end if;if v_monthly_limit>0 and v_used_month>=v_monthly_limit then return jsonb_build_object('allowed',false,'code','MONTHLY_LIMIT','tier',v_tier,'error','Monthly limit reached');end if;update public.profiles set generations_today=v_used_today+1,last_generation_date=v_today,generations_this_month=v_used_month+1,last_generation_month=v_month,updated_at=now() where id=p_user_id;return jsonb_build_object('allowed',true,'tier',v_tier,'remaining_today',case when v_daily_limit>0 then v_daily_limit-(v_used_today+1) else -1 end,'remaining_month',case when v_monthly_limit>0 then v_monthly_limit-(v_used_month+1) else -1 end,'bonus_remaining',v_bonus);end;$$;
